            editedAt: expect.any(Date),
          }),
        }),
      );
      expect(result.body).toBe('edited body');
      expect(result.editedAt).toBeInstanceOf(Date);
    });

    test('should throw an error when someone other than the author edits the comment', async () => {
      // Given
      const existingComment = {
        id: commentId,
        createdAt: minutesAgo(5),
        authorId: 999,
      };

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(existingComment);

      // Then
      await expect(updateComment('edited body', slug, commentId, authorId)).rejects.toThrowError();
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should throw an error when the comment is older than 15 minutes', async () => {
